{"statements": [
  {
   "id": "3.2.2a",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "text (\"should\")",
   "text": "a driver SHOULD keep to the right WHEN on a freeway BECAUSE the left lanes are for passing",
   "sources": [
    {
     "id": "m32",
     "quote": "Traffic should keep to the right, using the left lanes for passing."
    }
   ],
   "flags": [
    {
     "code": "X",
     "span": "keep to the right, using the left lanes for passing",
     "note": "m33 and m34 state the same advice as 'drive in the right-hand lane' with different additions."
    }
   ],
   "links": [],
   "note": "The condition 'on a freeway' comes from the heading 'Driving along a freeway'."
  },
  {
   "id": "3.2.2b",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"Use\", \"don't stay\")",
   "text": "a driver SHOULD use the far-left lane to pass traffic moving slower than the speed limit AND SHOULD NOT stay in the far-left lane WHEN on a multi-lane freeway",
   "sources": [
    {
     "id": "m33",
     "quote": "Use the far left lane of a multi-lane freeway to pass traffic moving slower than the speed limit, but don't stay there."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.2.2c",
   "type": "RULE",
   "force": "LEGAL",
   "force_from": "text (\"cannot travel\", \"must use\")",
   "text": "a driver of a large truck MUST NOT travel in the far-left lane AND MUST use the lane to the right for passing WHEN on a freeway with three or more lanes in each direction",
   "sources": [
    {
     "id": "m91",
     "quote": "On many freeways with three or more lanes in each direction, large trucks cannot travel in the far left lane and must use the lane to the right for passing."
    }
   ],
   "flags": [
    {
     "code": "S",
     "span": "many",
     "note": "The handbook limits the scope to 'many' such freeways, not all."
    }
   ],
   "links": [],
   "note": null
  },
  {
   "id": "3.2.2d",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"Drive\", \"Get into the habit\")",
   "text": "a driver SHOULD drive in the right-hand lane WHEN on a freeway AND it is [?possible] BECAUSE this leaves the other lanes clear for passing",
   "sources": [
    {
     "id": "m33",
     "quote": "Drive in the right-hand lane when possible."
    },
    {
     "id": "m34",
     "quote": "Get into the habit of driving in the right lane, leaving the other lanes clear for passing."
    }
   ],
   "flags": [
    {
     "code": "J",
     "span": "possible",
     "note": "No criterion for when driving in the right-hand lane is not possible."
    },
    {
     "code": "X",
     "span": "Drive in the right-hand lane when possible / driving in the right lane, leaving the other lanes clear for passing",
     "note": "m32 states the same advice as 'keep to the right, using the left lanes for passing'; m33 adds 'when possible'; m34 gives the purpose."
    }
   ],
   "links": [],
   "note": "Combined from m33 and m34, both in paragraph 5, which give the same advice with different wording."
  }
]}
